<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Service;

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurpose;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway\UserConsentPurposesFilter;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway\UserConsentPurposesReadGateway;

final class UserConsentPurposePending
{
    public function __construct(
        private readonly UserConsentPurposesReadGateway $read,
    ) {
    }

    /**
     * Returns the subset of $purposes that still need a user decision.
     *
     * @param ConsentPurpose[] $purposes
     *
     * @return ConsentPurpose[]
     */
    public function pending(UserRef $user, array $purposes): array
    {
        if (!$purposes) {
            return [];
        }

        $purposeUids = array_map(static fn (ConsentPurpose $p): string => $p->uid(), $purposes);
        $filter = (new UserConsentPurposesFilter())->withUser($user)->withConsentPurposes($purposeUids);
        $decided = [];
        foreach ($this->read->list($filter)->values() as $consent) {
            $decided[$consent->getConsentPurpose()->uid()] = true;
        }

        return array_values(array_filter($purposes, static fn (ConsentPurpose $p): bool => !isset($decided[$p->uid()])));
    }
}
